mapper.select:
SELECT c.* FROM sms_coupon_history ch LEFT JOIN sms_coupon c ON ch.coupon_id = c.id WHERE ch.member_id = #{memberId}
AND ch.use_status = #{useStatus} AND NOW() > c.start_time AND c.end_time > NOW()
AND NOW() > c.end_time

mapper.update:
UPDATE sms_coupon_history
SET use_status = 1,
    use_time   = NOW(),
    order_id   = #{orderId},
    order_sn   = #{orderSn}
WHERE id = (
    SELECT id FROM (
        SELECT id
        FROM sms_coupon_history
        WHERE member_id = #{memberId}
          AND coupon_id = #{couponId}
          AND use_status = 0
        ORDER BY id
        LIMIT 1
    ) couponCandidate
)
